const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '1/3' },
      { kind: 'text', payload: '1/2' },
      { kind: 'text', payload: '从小到大：1/3 < 1/2' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var y = H * 0.55;
    var x0 = W * 0.08;
    var x1 = W * 0.92;
    var span = x1 - x0;
    var x13 = x0 + span / 3;
    var x12 = x0 + span / 2;
    var tick = 8;

    var axisCmds = [['M', x0, y], ['L', x1, y]];
    var tickCmds = [
      ['M', x0, y - tick], ['L', x0, y + tick],
      ['M', x13, y - tick], ['L', x13, y + tick],
      ['M', x12, y - tick], ['L', x12, y + tick],
      ['M', x1, y - tick], ['L', x1, y + tick]
    ];
    var arrowCmds = [['M', x1 - 12, y - 7], ['L', x1, y], ['L', x1 - 12, y + 7]];
    var dot13 = visualSdk.circle(x13, y, 6);
    var dot12 = visualSdk.circle(x12, y, 6);

    return {
      schemaVersion: 1,
      sceneId: 'number-line-third-and-half',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'axis', commands: axisCmds },
        { id: 'ticks', commands: tickCmds },
        { id: 'arrow', commands: arrowCmds },
        { id: 'dot13', commands: dot13 },
        { id: 'dot12', commands: dot12 }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'axis', fill: '#26354a', stroke: { width: 2, cap: 'round' } },
        { type: 'path', pathId: 'ticks', fill: '#26354a', stroke: { width: 2, cap: 'round' } },
        { type: 'path', pathId: 'arrow', fill: '#26354a', stroke: { width: 2, cap: 'round' } },
        { type: 'path', pathId: 'dot13', fill: '#c2410c' },
        { type: 'path', pathId: 'dot12', fill: '#c2410c' },
        { type: 'label', contentId: metrics[0].contentId, anchor: { x: x0, y: y + 16 }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
        { type: 'label', contentId: metrics[1].contentId, anchor: { x: x1, y: y + 16 }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
        { type: 'label', contentId: metrics[2].contentId, anchor: { x: x13, y: y - 16 }, hAlign: 'center', vAlign: 'bottom', color: '#c2410c' },
        { type: 'label', contentId: metrics[3].contentId, anchor: { x: x12, y: y - 16 }, hAlign: 'center', vAlign: 'bottom', color: '#c2410c' },
        { type: 'label', contentId: metrics[4].contentId, anchor: { x: W / 2, y: H * 0.86 }, hAlign: 'center', vAlign: 'middle', color: '#26354a' }
      ] }
    };
  }
};
